#!/usr/bin/env bash
# Instruction-count bounds (v0.3.0; docs/SOUNDNESS.md "Instruction-count bounds"). Real `janus verify` runs (not --audit-only), so the
# witness requirement is in force, on both ISAs (arm64: examples Max/LoadField; amd64: the same functions):
#   controls  examples/proofs/Max.lean and examples/proofs-amd64/Max/Proof.lean (correctness, within, atLeast and their witnesses), a
#             state-dependent (pure) bound: all VERIFIED
#   attacks   attacks/*.lean (generated by gen-attacks.py): each REJECTED, the reason pinned in test/redteam/lib/blocked-pins.tsv
#               W1   bound proved from an unsatisfiable precondition: no witness / a witness that drops the precondition
#               W2   a bound computed from the run (depends on the post-state)       W3  fuel off by one (not provable)
#               W4   RunsAtLeast whose precondition admits only a faulting call       W5  untied witnesses (EnsuresWithin / RunsAtLeastOnCall)
#               W6   def-wrapped EnsuresWithin (rejected like a def-wrapped Ensures: the statement must mention Extracted.program), and parts
#                    of a visible EnsuresWithin hidden in local defs (the bound of a run, the [RSP]-word precondition): the audit expands them
#               W7/W8 the [RSP]-word rule on EnsuresWithin / RunsAtLeastOnCall
# Usage: test/redteam/rounds/roundwithin/run-roundwithin.sh   (env: JANUS_AUDIT_BIN, JANUS_AUDIT_PREBUILT=1, ROUNDWITHIN_ONLY=ROW-REGEX)   Exits 1 if a row differs.
set -u
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../../.." && pwd)"
cd "$root" || exit 1
export PATH=/usr/local/go/bin:$PATH
R=test/redteam/rounds/roundwithin
J="${JANUS_AUDIT_BIN:-$root/$R/bin/janus}"
if [ -z "${JANUS_AUDIT_BIN:-}" ]; then mkdir -p "$(dirname "$J")"; go build -o "$J" ./cmd/janus || exit 1; fi
if [ "${JANUS_AUDIT_PREBUILT:-}" != 1 ]; then
  lake build Janus Janus.Tools.Audit janus-audit >/dev/null || { echo "lake build failed"; exit 1; }
  [ -f artifacts/examples-arm64 ] || scripts/build/build-examples.sh >/dev/null
  { [ -f artifacts/examples-amd64 ] && [ -d artifacts/amd64/HexDigit ]; } || bash scripts/build/build-examples-amd64.sh >/dev/null 2>&1
fi
W=$R/work; rm -rf "$W"; mkdir -p "$W"
T="$(mktemp -d "${TMPDIR:-/tmp}/janus-roundwithin.XXXXXX")" || exit 1
trap 'rm -rf "$T"' EXIT
mkdir -m 700 "$T/cache"; export JANUS_CACHE_DIR="${JANUS_CACHE_DIR:-$T/cache}"
. scripts/verify/example-contracts.sh
ext() { # name arch(arm64|amd64) outdir
  mapfile -t tg < <(scripts/verify/example-targets.sh "$1")
  "$J" extract "artifacts/examples-$2" "$(example_symbol "$1")" "$W/$3" ${tg[@]+"${tg[@]}"} >/dev/null 2>&1 || { echo "extract $1 ($2) failed"; exit 1; }
}
ext Max arm64 Max; ext LoadField arm64 LoadField; ext Max amd64 Max64; ext LoadField amd64 LoadField64
. "$root/test/redteam/lib/blocked.sh"
SCRIPT=rounds/roundwithin/run-roundwithin.sh
broken=()
blk() { # FILE THM: the block of THM in the run output FILE (the whole output for a one-theorem run)
  if grep -q '^=== ' "$1"; then awk -v n="=== $2: " 'index($0,n)==1{p=1;print;next} /^=== /{p=0} p' "$1"; else cat "$1"; fi
}
isver() { # BLOCK: a verified block
  case "$(head -1 <<<"$1")" in "=== "*": verified ===") return 0 ;; esac
  grep -q '^Verified: ' <<<"$1"
}
runrow() { # LABEL EXPECT FILE ART THMS(comma) TARGET [extra janus flags]
  local label=$1 expect=$2 file=$3 art=$4 thms=$5 target=$6 fl=${7:-} t status="" out verdict
  [ -z "${ROUNDWITHIN_ONLY:-}" ] || [[ "$label" =~ $ROUNDWITHIN_ONLY ]] || return 0   # ROUNDWITHIN_ONLY=REGEX: run only the matching rows (mutation tests)
  local -a targs=()
  for t in ${thms//,/ }; do targs+=(--theorem "Proof.$t"); done
  "$J" verify "$W/$art" --proof "$file" "${targs[@]}" --janus-root "$root" --no-result-cache $fl > "$W/$label.txt" 2>&1
  out="$(blk "$W/$label.txt" "Proof.$target")"
  if [ "$expect" = verified ]; then
    # every theorem of the run verified
    for t in ${thms//,/ }; do isver "$(blk "$W/$label.txt" "Proof.$t")" || status=BROKEN; done
    verdict="verified"; [ -n "$status" ] && verdict="NOT verified: $(grep -m1 -E '^Invalid' <<<"$out" | cut -c1-160)"
  else
    if isver "$out"; then status=BROKEN; verdict="VERIFIED"; else
      verdict="rejected"
      local why; why="$(blocked_check $SCRIPT "$label" "$out")"
      [ -n "$why" ] && { status=BROKEN; verdict="rejected for the wrong reason [$why]"; }
    fi
  fi
  printf '  %-26s %-8s %s%s\n' "$label" "$expect" "$verdict" "${status:+   <-- BROKEN}"
  [ -n "$status" ] && broken+=("$label")
  return 0
}
echo "== controls: the Max examples (arm64, amd64): within, atLeast and their witnesses"
runrow C1_arm64_max verified examples/proofs/Max.lean Max correctness,within,atLeast,Witness.within,Witness.atLeast,Witness.nonvacuous correctness
runrow C1_amd64_max verified examples/proofs-amd64/Max/Proof.lean Max64 correctness,within,atLeast,Witness.within,Witness.atLeast,Witness.nonvacuous correctness
A=$R/attacks
echo "== arm64"
runrow W9_state_bound_ctl verified $A/W9_state_dependent_bound_control.lean Max correctness,within,Witness.nonvacuous,Witness.within within
runrow W1_unsat_pre blocked $A/W1_unsat_pre.lean Max within within
runrow W1_unsat_pre+anw blocked $A/W1_unsat_pre.lean Max within within --allow-no-witness
runrow W1b_witness_drops_pre blocked $A/W1b_unsat_pre_witness_drops_pre.lean Max within,Witness.within Witness.within
runrow W2_bound_of_run blocked $A/W2_bound_depends_on_post.lean Max within,Witness.within within
runrow W3_offbyone_within blocked $A/W3_offbyone_within3.lean Max within within
runrow W3b_offbyone_atleast blocked $A/W3b_offbyone_atleast4.lean Max atLeast atLeast
runrow W4_faulting_pre blocked $A/W4_lower_bound_faulting_pre.lean LoadField atLeast0,Witness.atLeast0 Witness.atLeast0
runrow W5_untied_within blocked $A/W5_untied_witness.lean Max correctness,within,Witness.nonvacuous within
runrow W5_untied_within+anw blocked $A/W5_untied_witness.lean Max correctness,within,Witness.nonvacuous within --allow-no-witness
runrow W5b_witness_no_run blocked $A/W5b_witness_has_no_run.lean Max within,Witness.within Witness.within
runrow W5c_atleast_no_return blocked $A/W5c_atleast_witness_no_return.lean Max atLeast,Witness.atLeast Witness.atLeast
runrow W6a_defwrapped_with_witness blocked $A/W6a_defwrapped_with_witness.lean Max within,Witness.within within
runrow W6e_bound_in_local_def blocked $A/W6e_bound_in_local_def.lean Max within,Witness.within within
runrow W6c_defwrapped_untied blocked $A/W6c_defwrapped_untied.lean Max within within
runrow W6d_defwrapped_run_bound blocked $A/W6d_defwrapped_bound_of_run.lean Max within within
echo "== amd64"
runrow amd64_W6a_defwrapped_with_witness blocked $A/amd64_W6a_defwrapped_with_witness.lean Max64 within,Witness.within within
runrow amd64_W1_unsat_pre blocked $A/amd64_W1_unsat_pre.lean Max64 within within
runrow amd64_W1b_witness_drops blocked $A/amd64_W1b_unsat_pre_witness_drops_pre.lean Max64 within,Witness.within Witness.within
runrow amd64_W2_bound_of_run blocked $A/amd64_W2_bound_depends_on_post.lean Max64 within,Witness.within within
runrow amd64_W3_offbyone_within blocked $A/amd64_W3_offbyone_within3.lean Max64 within within
runrow amd64_W3b_offbyone_atleast blocked $A/amd64_W3b_offbyone_atleast4.lean Max64 atLeast atLeast
runrow amd64_W4_faulting_pre blocked $A/amd64_W4_lower_bound_faulting_pre.lean LoadField64 atLeast0,Witness.atLeast0 Witness.atLeast0
runrow amd64_W5_untied_within blocked $A/amd64_W5_untied_witness.lean Max64 correctness,within,Witness.nonvacuous within
runrow amd64_W5b_witness_no_run blocked $A/amd64_W5b_witness_has_no_run.lean Max64 within,Witness.within Witness.within
runrow amd64_W5c_atleast_no_return blocked $A/amd64_W5c_atleast_witness_no_return.lean Max64 atLeast,Witness.atLeast Witness.atLeast
runrow amd64_W7_rsp_word blocked $A/amd64_W7_rsp_word_in_pre.lean Max64 within,Witness.within within
runrow amd64_W6b_defwrapped_rsp blocked $A/amd64_W6b_defwrapped_rsp_word.lean Max64 within within
runrow amd64_W6e_pre_in_local_def blocked $A/amd64_W6e_pre_in_local_def.lean Max64 within,Witness.within within
runrow amd64_W8_atleast_rsp blocked $A/amd64_W8_atleast_rsp_word.lean Max64 atLeast,Witness.atLeast atLeast
echo
if [ ${#broken[@]} -gt 0 ]; then echo "round within: BROKEN rows: ${broken[*]}"; exit 1; fi
echo "round within: all rows as expected"
